-- EMERGENCY ROLLBACK 083 (production). Generated by docs/releases/production-075/gen-emergency-rollback.py.
-- Run ONLY with the owner's approval, in ONE transaction:
--   psql "<production connection>" -X -v ON_ERROR_STOP=1 --single-transaction -f docs/releases/production-075/emergency/rollback_083_with_history.sql
-- Order: newest first (086, 085, 084, 083, 082, 081, 080, 079, 078, 077, 076, 075, 074, 073). Keeps every business row; removes the 083 history row so the migration history
-- matches the schema again (the plain supabase/rollback file does not touch supabase_migrations).
set lock_timeout = '10s';
set statement_timeout = '5min';
do $guard$
begin
  if to_regprocedure('public.deployment_environment()') is not null then
    raise exception 'STOP: JewelryFlow SaaS demo database, not Goldia';
  end if;
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20260101000083') then
    raise exception 'STOP: migration 083 is not recorded — nothing to roll back';
  end if;
  if exists (select 1 from supabase_migrations.schema_migrations where version > '20260101000083') then
    raise exception 'STOP: a newer migration is recorded — roll that back first';
  end if;
end $guard$;

